--
-- Create procedure `Proc_Unit_CheckListNames`
--
CREATE PROCEDURE Proc_Unit_CheckListNames (IN `@Names` text, OUT `@ListNameInvalid` text)
SQL SECURITY INVOKER
COMMENT 'Proc kiểm tra xem chuỗi tên có hợp lệ không'
BEGIN
  DECLARE `@UnitName` nvarchar(50);
  CREATE TEMPORARY TABLE IF NOT EXISTS TempInvalidInventory (
    UnitName nvarchar(50)
  );
  -- Tách chuỗi SKUCode thành các giá trị riêng biệt và lặp qua từng SKUCode
  WHILE LENGTH(`@Names`) > 0 DO
    SET `@UnitName` = SUBSTRING_INDEX (`@Names`, ',', 1);
    -- Kiểm tra xem position có tồn tại trong bảng employee hay không
    IF EXISTS (SELECT
          1
        FROM unit u
        WHERE u.UnitName = `@UnitName`) THEN
      -- Thêm Position ID vào bảng nếu không tồn tại khóa ngoại
      INSERT INTO TempInvalidInventory (UnitName)
        VALUES (`@UnitName`);
    END IF;
    -- Loại bỏ SKUCode đã xử lý từ chuỗi 
    -- SUBString "12,2,3,4" khi bỏ 12 thì bắt đầu từ vị trí 4=> 2,3,4 Trim bỏ , thành khoảng trắng 2 3 4 lặp cho đến khi hết
    SET `@Names` = TRIM(BOTH ',' FROM SUBSTRING(`@Names`, LENGTH(`@UnitName`) + 2));
  END WHILE;
  -- trả về chuỗi code không hợp lệ
  SELECT
    GROUP_CONCAT(UnitName SEPARATOR ', ') INTO `@ListNameInvalid`
  FROM TempInvalidInventory;
  DROP TEMPORARY TABLE IF EXISTS TempInvalidInventory;
END
$$

DELIMITER ;

