--
-- Create procedure `Proc_ItemCategory_CheckListCodes`
--
CREATE PROCEDURE Proc_ItemCategory_CheckListCodes (IN `@Codes` text, OUT `@ListCodeInvalid` text)
SQL SECURITY INVOKER
COMMENT 'Proc kiểm tra xem chuỗi mã  có hợp lệ không'
BEGIN
  DECLARE `@ItemCode` nvarchar(50);
  CREATE TEMPORARY TABLE IF NOT EXISTS TempInvalidInventory (
    ItemCategoryCode nvarchar(50)
  );
  -- Tách chuỗi SKUCode thành các giá trị riêng biệt và lặp qua từng SKUCode
  WHILE LENGTH(`@Codes`) > 0 DO
    SET `@ItemCode` = SUBSTRING_INDEX (`@Codes`, ',', 1);
    -- Kiểm tra xem position có tồn tại trong bảng employee hay không
    IF EXISTS (SELECT
          1
        FROM itemcategory i
        WHERE i.ItemCategoryCode = `@ItemCode`) THEN
      -- Thêm Position ID vào bảng nếu không tồn tại khóa ngoại
      INSERT INTO TempInvalidInventory (ItemCategoryCode)
        VALUES (`@ItemCode`);
    END IF;
    -- Loại bỏ SKUCode đã xử lý từ chuỗi 
    -- SUBString "12,2,3,4" khi bỏ 12 thì bắt đầu từ vị trí 4=> 2,3,4 Trim bỏ , thành khoảng trắng 2 3 4 lặp cho đến khi hết
    SET `@Codes` = TRIM(BOTH ',' FROM SUBSTRING(`@Codes`, LENGTH(`@ItemCode`) + 2));
  END WHILE;
  -- trả về chuỗi code không hợp lệ
  SELECT
    GROUP_CONCAT(ItemCategoryCode SEPARATOR ', ') INTO `@ListCodeInvalid`
  FROM TempInvalidInventory;
  DROP TEMPORARY TABLE IF EXISTS TempInvalidInventory;
END
$$

