--
-- Create procedure `Proc_Inventory_Update`
--
CREATE PROCEDURE Proc_Inventory_Update (IN `@InventoryId` char(36), IN `@InventoryName` varchar(100), IN `@SKUCode` varchar(50), IN `@SKUCodeCustom` varchar(50), IN `@Barcode` varchar(50), IN `@CostPrice` decimal(18, 0), IN `@UnitPrice` decimal(18, 0), IN `@AvgUnitPrice` decimal(18, 0), IN `@AvgCostPrice` decimal(18, 0), IN `@Color` varchar(50), IN `@ColorCode` varchar(50), IN `@Size` varchar(50), IN `@SizeCode` varchar(50), IN `@Description` varchar(255), IN `@PictureId` char(36), IN `@IsActive` tinyint, IN `@IsShowMenu` tinyint, IN `@ParentId` char(36), IN `@ItemCategoryId` char(36), IN `@UnitId` char(36), IN `@ModifiedDate` datetime, IN `@ModifiedBy` datetime)
SQL SECURITY INVOKER
BEGIN
  UPDATE inventory i
  SET InventoryName = `@InventoryName`,
      SKUCode = `@SKUCode`,
      Barcode = `@Barcode`,
      CostPrice = `@CostPrice`,
      UnitPrice = `@UnitPrice`,
      Color = `@Color`,
      ColorCode = `@ColorCode`,
      Size = `@Size`,
      SizeCode = `@SizeCode`,
      Description = `@Description`,
      PictureId = `@PictureId`,
      IsActive = `@IsActive`,
      IsShowMenu = `@IsShowMenu`,
      ParentId = `@ParentId`,
      ItemCategoryId = `@ItemCategoryId`,
      UnitId = `@UnitId`,
      ModifiedBy = `@ModifiedBy`,
      ModifiedDate = `@ModifiedDate`,
      AvgUnitPrice = `@AvgUnitPrice`,
      AvgCostPrice = `@AvgCostPrice`,
      SKUCodeCustom = `@SKUCodeCustom`
  WHERE InventoryId = `@InventoryId`;
END
$$

