--
-- Create view `view_inventory_detail`
--
CREATE
DEFINER = 'root'@'localhost'
VIEW view_inventory_detail
AS
SELECT
  `i`.`InventoryId` AS `InventoryId`,
  `i`.`InventoryName` AS `InventoryName`,
  `i`.`SKUCode` AS `SKUCode`,
  `i`.`SKUCodeCustom` AS `SKUCodeCustom`,
  `i`.`Barcode` AS `Barcode`,
  `i`.`CostPrice` AS `CostPrice`,
  `i`.`UnitPrice` AS `UnitPrice`,
  `i`.`Color` AS `Color`,
  `i`.`ColorCode` AS `ColorCode`,
  `i`.`Size` AS `Size`,
  `i`.`SizeCode` AS `SizeCode`,
  `i`.`Description` AS `Description`,
  `p`.`PictureName` AS `PictureName`,
  `i`.`IsActive` AS `IsActive`,
  `i`.`IsShowMenu` AS `IsShowMenu`,
  `i`.`ParentId` AS `ParentId`,
  `i`.`ItemCategoryId` AS `ItemCategoryId`,
  `u`.`UnitId` AS `UnitId`,
  `it`.`ItemCategoryName` AS `ItemCategoryName`,
  `u`.`UnitName` AS `UnitName`,
  `i`.`AvgUnitPrice` AS `AvgUnitPrice`,
  `i`.`AvgCostPrice` AS `AvgCostPrice`
FROM (((`inventory` `i`
  LEFT JOIN `itemcategory` `it`
    ON (`i`.`ItemCategoryId` = `it`.`ItemCategoryId`))
  LEFT JOIN `unit` `u`
    ON (`i`.`UnitId` = `u`.`UnitId`))
  LEFT JOIN `picture` `p`
    ON (`i`.`PictureId` = `p`.`PictureId`))
WHERE `i`.`ParentId` IS NOT NULL
ORDER BY `i`.`CreatedDate` DESC;

