--
-- Create table `code`
--
CREATE TABLE code (
  TableName varchar(255) NOT NULL DEFAULT '',
  Prefix varchar(255) NOT NULL DEFAULT '',
  Value varchar(255) NOT NULL DEFAULT '',
  NewValue varchar(255) NOT NULL DEFAULT '' COMMENT 'Bảng chứa mã code'
)
ENGINE = INNODB,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci;

DELIMITER $$

--
-- Create procedure `Proc_Code_Update`
--
CREATE PROCEDURE Proc_Code_Update (IN `@TableName` varchar(255), IN `@Prefix` varchar(255))
SQL SECURITY INVOKER
COMMENT 'Proc cập nhật mã mới'
BEGIN
  DECLARE `@OldPrefix` varchar(50);
  SELECT
    c.Prefix INTO `@OldPrefix`
  FROM code c
  WHERE c.TableName = `@TableName`
  AND `@Prefix` = c.Prefix;
  IF `@OldPrefix` IS NULL THEN
    INSERT INTO code (TableName, Prefix, Value, NewValue)
      VALUES (`@TableName`, `@Prefix`, '00', '00');
  ELSE
    UPDATE `Code` c
    SET c.Value = c.NewValue
    WHERE c.Prefix = `@Prefix`
    AND `@TableName` = c.TableName;
  END IF;


END
$$

--
-- Create procedure `Proc_Code_GetNewCode`
--
CREATE PROCEDURE Proc_Code_GetNewCode (IN `@TableName` varchar(255), IN `@Prefix` varchar(50), OUT `@NewCode` varchar(50))
SQL SECURITY INVOKER
COMMENT 'Proc lấy mã mới theo tên bảng và prefix'
BEGIN
  DECLARE `@CheckExits` char(36);
  -- giá trị của mã đi cùng prifix
  DECLARE `@Value` varchar(255);
  -- Length của Number
  DECLARE `@DigitCount` int;
  -- Lấy được giá trị của prifix
  SELECT
    c.Value INTO `@Value`
  FROM code c
  WHERE c.Prefix = `@Prefix`
  AND `@TableName` = c.TableName;

  IF `@Value` IS NULL THEN
    SET `@NewCode` = `@Prefix`;
  ELSE
    SET `@DigitCount` = CHAR_LENGTH(`@Value`);
    IF `@DigitCount` = CHAR_LENGTH(CAST(`@Value` AS SIGNED)) THEN
      -- Lưu độ dài mới của value + 1 nếu là 09 thì + 1 kết quả là 2
      SET `@DigitCount` = CHAR_LENGTH(CAST(`@Value` + 1 AS SIGNED));
    END IF;
    SET `@Value` = LPAD(`@Value` + 1, `@DigitCount`, '0');
    SET `@NewCode` = CONCAT(`@Prefix`, '', `@Value`);

    UPDATE code c
    SET c.NewValue = `@Value`
    WHERE `@Prefix` = c.Prefix
    AND c.TableName = `@TableName`;
    -- Nếu mã mới trùng thì tăng 1
    SELECT
      i.InventoryId INTO `@CheckExits`
    FROM inventory i
    WHERE i.SKUCode = `@NewCode`;
    IF `@CheckExits` IS NOT NULL THEN
      SET `@Value` = LPAD(`@Value` + 1, `@DigitCount`, '0');
      SET `@NewCode` = CONCAT(`@Prefix`, '', `@Value`);
      CALL Proc_Code_Update(`@TableName`, `@Prefix`);
    END IF;
  END IF;
END
$$

DELIMITER ;

--
-- Create table `role`
--
CREATE TABLE role (
  RoleID char(36) NOT NULL DEFAULT '',
  RoleType varchar(50) NOT NULL,
  RoleName varchar(50) NOT NULL DEFAULT '',
  Description varchar(255) DEFAULT NULL,
  CreatedDate datetime DEFAULT NULL COMMENT 'Ngày tạo',
  CreatedBy varchar(255) DEFAULT NULL COMMENT 'Người tạo',
  ModifiedBy varchar(255) DEFAULT NULL COMMENT 'Người sửa',
  ModifiedDate datetime DEFAULT NULL COMMENT 'Ngày sửa'
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 8192,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
COMMENT = 'Quyền người dùng';

DELIMITER $$

--
-- Create procedure `Proc_User_GetById`
--
CREATE PROCEDURE Proc_User_GetById (IN `@Id` char(36))
SQL SECURITY INVOKER
COMMENT 'lấy user theo id'
BEGIN
  SELECT
    u.UserID,
    u.UserCode,
    u.UserName,
    u.Password,
    u.Email,
    u.AddressID,
    u.CreatedDate,
    u.CreatedBy,
    u.ModifiedBy,
    u.ModifiedDate,
    RoleType,
    RoleName
  FROM user u
    LEFT JOIN `role` r
      ON u.RoleID = r.RoleID
  WHERE UserID = `@Id`;
END
$$

--
-- Create procedure `Proc_User_GetAll`
--
CREATE PROCEDURE Proc_User_GetAll ()
SQL SECURITY INVOKER
COMMENT 'Lấy tất cả user'
BEGIN
  SELECT
    UserName,
    UserID,
    Email,
    UserCode,
    AddressID,
    RoleType,
    RoleName
  FROM user
    LEFT JOIN `role`
      ON `user`.RoleID = `ROLE`.RoleID;
END
$$

--
-- Create procedure `Proc_Role_GetAll`
--
CREATE PROCEDURE Proc_Role_GetAll ()
SQL SECURITY INVOKER
COMMENT 'Lấy tất cả quyền'
BEGIN
  SELECT
    *
  FROM `Role`;
END
$$

DELIMITER ;

--
-- Create table `user`
--
CREATE TABLE user (
  UserID char(36) NOT NULL DEFAULT '',
  UserCode varchar(50) NOT NULL DEFAULT '',
  UserName varchar(100) NOT NULL DEFAULT '',
  Password varchar(50) NOT NULL DEFAULT '',
  Email varchar(50) DEFAULT NULL,
  AddressID char(36) DEFAULT NULL,
  CreatedDate datetime DEFAULT NULL,
  CreatedBy varchar(255) DEFAULT NULL,
  ModifiedBy varchar(255) DEFAULT NULL,
  ModifiedDate datetime DEFAULT NULL,
  RoleID char(36) DEFAULT NULL
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 16384,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
COMMENT = 'Bảng user';

DELIMITER $$

--
-- Create procedure `Proc_Role_GetById`
--
CREATE PROCEDURE Proc_Role_GetById (IN `@Id` char(36))
SQL SECURITY INVOKER
COMMENT 'lấy Role theo id'
BEGIN
  SELECT
    r.RoleID,
    r.RoleType,
    r.RoleName,
    r.Description
  FROM role r
  WHERE RoleID = `@Id`;
END
$$

--
-- Create procedure `Proc_ItemCategory_GetByIds`
--
CREATE PROCEDURE Proc_ItemCategory_GetByIds (IN `@Ids` text)
SQL SECURITY INVOKER
COMMENT 'lấy danh sách đơn vị tính theo chuỗi ids'
BEGIN
  -- lấy danh sách theo chuỗi ids
  SELECT
    vi.ItemCategoryCode,
    vi.ItemCategoryName,
    vi.Description
  FROM view_itemcategory vi
  WHERE FIND_IN_SET(vi.ItemCategoryId, `@Ids`) > 0;
END
$$

--
-- Create procedure `Proc_Filter`
--
CREATE PROCEDURE Proc_Filter (IN `@QueryLimit` text, OUT `@TotalRecords` int, IN `@QueryWhere` text, IN `@QueryOrder` text, IN `@TableName` varchar(255), IN `@QueryCode` text)
SQL SECURITY INVOKER
COMMENT 'Proc phân trang tìm kiếm lọc'
BEGIN
  SET @query = CONCAT('Select SQL_CALC_FOUND_ROWS *', `@QueryCode`, ' from view_', `@TableName`, ' as view ', `@QueryWhere`, `@QueryOrder`, `@QueryLimit`);
  PREPARE stmt FROM @query;
  EXECUTE stmt;
  DEALLOCATE PREPARE stmt;

  SELECT
    FOUND_ROWS() INTO `@TotalRecords`;
END
$$

--
-- Create procedure `Proc_Excute`
--
CREATE PROCEDURE Proc_Excute (IN `@QueryString` text)
SQL SECURITY INVOKER
COMMENT 'Proc để chạy truy vấn'
BEGIN
  SET @query = `@QueryString`;
  PREPARE stmt FROM @query;
  EXECUTE stmt;
  DEALLOCATE PREPARE stmt;
END
$$

DELIMITER ;

